  "high_order_assessment": [
    {
      "active_model_action": true,
      "citations": [
        {
          "event_id": "lite_evt_00084",
          "explanation": "The doctor offered an adapted transport pathway rather than requiring the patient to wait indefinitely for accompaniment.",
          "quote": "有人陪同当然更安全"
        },
        {
          "event_id": "lite_evt_00078",
          "explanation": "The patient confirmed a specific nearby hospital, accompaniment plan, and records preparation.",
          "quote": "附近那个有急诊和消化内科的医院"
        }
